mapper.select:
SELECT om.id, om.organization_id, om.user_id, om.role, om.status, om.created_at, om.updated_at
FROM organization_member om
WHERE om.organization_id = #{organizationId}
  AND om.user_id = #{userId}
  AND om.status = 'ACTIVE'
FOR UPDATE

SELECT id, user_id, token_hash, issued_at, expires_at, revoked_at, replaced_by_token_id, ip_address, user_agent
FROM refresh_token
WHERE token_hash = #{tokenHash}

mapper.update:
UPDATE refresh_token
SET revoked_at = #{revokedAt}, replaced_by_token_id = #{replacedByTokenId}
WHERE id = #{id}

UPDATE refresh_token
SET revoked_at = #{revokedAt}
WHERE user_id = #{userId} AND revoked_at IS NULL

mapper.select:
SELECT id, user_id, token_hash, expires_at, used_at, created_at
FROM password_reset_token
WHERE token_hash = #{tokenHash}

mapper.update:
UPDATE password_reset_token
SET used_at = #{usedAt}
WHERE id = #{id}
